import React from "react";
import { ConsensusEventMessage } from "../ExplorerTestPage";
import { ConsensusEventItem } from "./ConsensusEventItem";

interface ConsensusEventListProps {
  events: ConsensusEventMessage[];
}

export const ConsensusEventList: React.FC<ConsensusEventListProps> = ({
  events,
}) => {
  if (events.length === 0) {
    return (
      <div className="consensus-event-list empty">
        <p>No events received yet. Connect and subscribe to start receiving consensus events.</p>
      </div>
    );
  }

  return (
    <div className="consensus-event-list">
      <div className="event-list-header">
        <h3>Consensus Events ({events.length})</h3>
      </div>
      <div className="event-items">
        {events.map((event) => (
          <ConsensusEventItem key={event.id} message={event} />
        ))}
      </div>
    </div>
  );
};

