  /**
   * Get user trades for an address
   * Uses HTTP endpoint /clob/v1/address/trades (matches Go client GetUserTrades)
   * Response format: { trades: RawTrade[], total_count: number, market_id: string, symbol: string, timestamp: string }
   */
  async getUserTrades(
    address: string,
    assetPair?: string,
  ): Promise<RawTrade[]> {
    let path = `/clob/v1/address/trades?address=${address}`;
    if (assetPair) {
      path += `&asset_pair=${assetPair}`;
    }
    const response = await this.httpClient.get(path, this.getHeaders());
    const body = response.body as TradesResponse;

    // Handle the actual API response structure
    if (
      body &&
      typeof body === "object" &&
      "trades" in body &&
      Array.isArray(body.trades)
    ) {
      return body.trades;
    }

    // Fallback for legacy formats (direct array or { data: [...] })
    if (Array.isArray(body)) {
      return body;
    }
    // Check for legacy format with 'data' property (not part of TradesResponse type)
    const bodyAny = body as any;
    if (bodyAny?.data && Array.isArray(bodyAny.data)) {
      return bodyAny.data;
    }

    return [];
  }

  /**
   * Get trade history (alias for getUserTrades)
   */
  async getTradeHistory(
    address: string,
    assetPair?: string,
  ): Promise<RawTrade[]> {
    return this.getUserTrades(address, assetPair);
  }

