/**
 * API response types
 */

export interface ApiResponse<T = any> {
  success: boolean;
  data?: T;
  error?: string;
  message?: string;
  requestId?: string;
}

export type SubscriptionCallback = (data: any) => void;

// ============================================================================
// BUCKET TYPES
// ============================================================================

/**
 * Raw bucket data structure as returned from the API
 * All numeric values are strings in satoshi format
 * Field names are in snake_case format
 *
 * This matches the actual API response format from /bucket/v1/address/{address}/buckets
 */
export interface RawBucket {
  bucket_id: string;
  address: string;
  margin_type: string; // e.g., "cross", "isolated"
  collateral_asset: string; // e.g., "USDC"
  deposited_margin: string; // Satoshi format (string) - total margin deposited
  total_equity: string; // Satoshi format (string)
  available_margin: string; // Satoshi format (string)
  used_margin: string; // Satoshi format (string)
  unrealized_profit: string; // Satoshi format (string)
  unrealized_loss: string; // Satoshi format (string)
  realized_profit: string; // Satoshi format (string)
  realized_loss: string; // Satoshi format (string)
  margin_ratio: string; // Satoshi format (string) - margin ratio
  imr: string; // Initial Margin Requirement (as string, e.g., "10" for 10%)
  total_notional_value: string; // Satoshi format (string)
  risk_level: string; // e.g., "low", "medium", "high"
  max_leverage: string | number; // Can be string "20" or number
  correlation_offset: number; // Correlation offset (number)
  status: string; // e.g., "dormant", "active"
  created_at: string | Timestamp; // ISO timestamp string OR protobuf Timestamp object { seconds, nanos }
  updated_at: string | Timestamp; // ISO timestamp string OR protobuf Timestamp object { seconds, nanos }
  sequence_id?: string; // Sequence ID (optional, may not be present in all responses)
}

/**
 * WebSocket buckets update message structure
 * Format: { buckets: RawBucket[], total_buckets: number, address: string, timestamp: number }
 */
export interface BucketsUpdateMessage {
  buckets: RawBucket[];
  total_buckets: number;
  address: string;
  timestamp: number;
  [key: string]: any; // Allow additional fields
}

